#include "etazero/search.h"
#include <iostream>
using namespace etazero;
struct EqualState : SearchState {
    int action=-1;
    std::unique_ptr<SearchState> clone() const override { return std::make_unique<EqualState>(*this); }
    int actions() const override { return 2; }
    bool legal(int a) const override { return action<0 && a>=0 && a<2; }
    bool terminal() const override { return action>=0; }
    double terminal_value() const override { return 0; }
    Evaluation evaluate(SearchEvaluation = {}) const override { return {{0,0},{.5,0,.5}}; }
    int move(int a) override { action=a; return -1; }
};
int main() {
    int counts[2]={0,0};
    for(int seed=0; seed<100; ++seed) {
        SearchSettings settings{1,1,1.5,3,0,6.75,false};
        settings.max_playouts=2;
        settings.max_visits=2;
        settings.value_weight_exponent=0;
        settings.chosen_move_prune=0;
        Search search(settings,seed);
        auto result=search.run(EqualState(),0);
        if(result.simulations!=1)throw std::runtime_error("Expected one root-edge simulation");
        for(int i=0;i<2;++i)if(result.visits[i]>0)++counts[i];
    }
    std::cout<<"{\"seeds\":100,\"first_child_counts\":["<<counts[0]<<","<<counts[1]<<"]}\n";
}
